// TSP Bitmask DP - minimum cost Hamiltonian circuit
function tsp(dist) {
  const n = dist.length;
  const fullMask = (1 << n) - 1;
  // dp[mask][i] = min cost visiting nodes in mask, ending at i
  const INF = Infinity;
  const dp = Array.from({ length: 1 << n }, () => new Array(n).fill(INF));
  dp[1][0] = 0; // start at node 0, mask = 0b...0001

  for (let mask = 1; mask <= fullMask; mask++) {
    for (let i = 0; i < n; i++) {
      if (!(mask & (1 << i))) continue; // i must be in mask
      if (dp[mask][i] === INF) continue; // unreachable state

      for (let j = 0; j < n; j++) {
        if (mask & (1 << j)) continue; // j already visited
        const newMask = mask | (1 << j);
        dp[newMask][j] = Math.min(dp[newMask][j], dp[mask][i] + dist[i][j]);
      }
    }
  }

  // return to start: min cost over all ending nodes
  let ans = INF;
  for (let i = 1; i < n; i++) {
    if (dp[fullMask][i] !== INF) {
      ans = Math.min(ans, dp[fullMask][i] + dist[i][0]);
    }
  }
  return ans;
}
